class Solution(object):
    def grayCode(self, n):
        """
        :type n: int
        :rtype: List[int]
        """
        ret = [0]
        num = 0
        while True:
            for i in range(n):
                m = 1<<i
                if num^m not in ret:
                    num = num^m
                    ret.append(num)
                    break
            else:
                break
        return ret

class Solution(object):
    def grayCode(self, n):
        """
        :type n: int
        :rtype: List[int]
        """
        ans = [0]
        for i in range(n):
            ans += [x + 2 ** i for x in reversed(ans)]
        return ans
